use super::kit::*;
pub fn commands()->Vec<Command>{vec![Command{name:"inspect_film_response",description:"Measure declared film shoulder curve and luma-grain density without modifying the project. Opt-in effects available through add_effect; native OCIO domains through explicit effect strings.",mutates:false,schema:obj(vec![("knee",n("shoulder knee0..1")),("peak",n("peak>knee")),("shadow_density",n("0..1")),("highlight_density",n("0..1")),("falloff",n("0.1..8"))],&[]),run:|_,a|{let params:crate::effects::Params=a.as_object().ok_or("object required")?.iter().map(|(k,v)|Ok((k.clone(),crate::keyframe::Prop::new(v.as_f64().ok_or("numeric response parameter required")?)))).collect::<Result<_,String>>()?;let mut f=crate::effects::Frame{w:1,h:1,d:vec![0.,0.,0.,1.]};crate::color::film_response::apply("film_soft_shoulder",&params,&mut f,0.,0)?;crate::color::film_response::apply("film_luma_grain",&params,&mut f,0.,0)?;let knee=opt_num(a,"knee",0.75) as f32 as f64;let peak=opt_num(a,"peak",1.) as f32 as f64;let sd=opt_num(a,"shadow_density",0.9) as f32 as f64;let hd=opt_num(a,"highlight_density",0.08) as f32 as f64;let fall=opt_num(a,"falloff",1.5) as f32 as f64;Ok(json!({"shoulder":([0.,0.18,0.5,0.75,1.,2.,4.,16.].map(|x|json!({"input":x,"output":crate::color::film_response::shoulder(x,knee,peak)}))),"grain_density":([0.,0.18,0.5,0.75,1.].map(|l|json!({"luma":l,"occupancy":crate::color::film_response::density(l,sd,hd,fall)}))),"domain":"Caller-declared signal, not inferred. Grain luma assumes display Rec709. Native OCIO effect sandwich needs explicit spaces, not an inverse display/view guess.","clipping":false,"stock_calibrated":false}))}}]}
